// Before fusion
%c = matmul(%a, %b)          : tensor<M x K> * tensor<K x N> -> tensor<M x N>
%d = add(%c, %bias)          : tensor<M x N>
%e = gelu(%d)                : tensor<M x N>

// After epilogue fusion (candidate rewrite)
%e = matmul_epilogue(%a, %b, %bias)
     { epilogue = [add_bias, gelu] }
     : (tensor<M x K>, tensor<K x N>, tensor<N>) -> tensor<M x N>

// Before fusion
for i in 0..N:
    B[i] = f(A[i])                // producer loop
for i in 0..N:
    C[i] = g(B[i-1], B[i], B[i+1])  // consumer with cross-iteration reads

// Proposed fused loop
for i in 0..N:
    B[i] = f(A[i])
    C[i] = g(B[i-1], B[i], B[i+1])   // reads B[i-1], B[i], B[i+1]

// Order 1: i-j-k
for i in 0..M:
  for j in 0..N:
    for k in 0..K:
      C[i,j] += A[i,k] * B[k,j]      // inner loop walks k: A row-wise (unit stride), B column-wise (stride N)

// Order 2: i-k-j
for i in 0..M:
  for k in 0..K:
    for j in 0..N:
      C[i,j] += A[i,k] * B[k,j]      // inner loop walks j: B[k,:] unit stride, C[i,:] unit stride, A[i,k] is a scalar in the inner loop

